	CREATE PROCEDURE CopyNonHTTPMessageHeaders() BEGIN
		DECLARE H INTEGER 1;
		DECLARE I INTEGER 1;
		DECLARE J INTEGER;
		SET J = CARDINALITY(InputRoot.*[]);
		WHILE I < J DO
			IF NOT CONTAINS(InputRoot.*[I], 'HTTP') THEN
				SET OutputRoot.*[H] = InputRoot.*[I];
				SET H = H + 1;
			END IF;
			SET I = I + 1;
		END WHILE;
	END;
END MODULE;

